Here's a C++ program that generates the Fibonacci sequence using a recursive function:

```cpp
#include <iostream>
#include <string>
#include <sstream>
#include <stdexcept>

using namespace std;

int fibonacci(int n) {
    if (n <= 1) {
        return n;
    } else {
        return fibonacci(n - 1) + fibonacci(n - 2);
    }
}

int main() {
    int firstNum, secondNum, numElements;
    string input;

    cout << "Enter the first two integers: ";
    getline(cin, input);

    istringstream iss(input);
    iss >> firstNum >> secondNum;

    if (!iss || firstNum < 0 || secondNum < 0) {
        throw runtime_error("Invalid input. Please enter non-negative integers.");
    }

    cout << "Enter the number of sequence elements to generate: ";
    cin >> numElements;

    if (numElements <= 0) {
        throw runtime_error("Invalid input. Please enter a positive integer.");
    }

    vector<int> sequence(numElements);
    sequence[0] = firstNum;
    sequence[1] = secondNum;

    for (int i = 2; i < numElements; i++) {
        sequence[i] = fibonacci(i);
    }

    cout << "Fibonacci sequence: ";
    for (int i = 0; i < numElements; i++) {
        cout << sequence[i] << ", ";
    }
    cout << endl;

    return 0;
}
```

This program prompts the user to enter the first two integers and the number of sequence elements to generate. It then generates the Fibonacci sequence using a recursive function and outputs the result. The program includes error handling for invalid inputs, such as non-numeric inputs or negative numbers.

