def english_number_to_words(num: int) -> str:
    if num == 0:
        return "zero"
    elif num < 0:
        return "negative " + english_number_to_words(-num)
    else:
        words = []
        while num >= 1000:
            words.append(str(num % 1000))
            num //= 1000
        if num >= 100:
            words.append(str(num % 100))
            num //= 100
        if num >= 10:
            words.append(str(num % 10))
            num //= 10
        words.reverse()
        return " ".join(words)

def english_scientific_notation_to_words(num_str: str) -> str:
