const Image = mongoose.model('Image', ImageSchema);

// Create a file stream and write the image data to it
const fileStream = fs.createReadStream('path/to/your/image.jpg');

// Create a gridfs stream and write the file data to MongoDB
const gfs = gridfs(mongoose.connection.db);
const writeStream = gfs.createWriteStream({
  filename: 'your_image_filename.jpg',
  contentType: 'image/jpeg',
});

fileStream.pipe(writeStream);

// Once the file is written to MongoDB, you can retrieve it using the following code:
