```sql
CREATE FUNCTION validate_celsius(celsius DECIMAL) RETURNS BOOLEAN AS $$
BEGIN
    IF celsius IS NULL OR celsius < -273.15 THEN
        RETURN FALSE;
    END IF;
    RETURN TRUE;
END;
$$ LANGUAGE plpgsql;

CREATE FUNCTION convert_celsius_to_fahrenheit(celsius DECIMAL) RETURNS DECIMAL AS $$
BEGIN
    IF NOT validate_celsius(celsius) THEN
        RAISE_APPLICATION_ERROR(1, 'Invalid Celsius value');
    END IF;
    RETURN (celsius * 9/5) + 32;
END;
$$ LANGUAGE plpgsql;

SELECT convert_celsius_to_fahrenheit(30); -- Output: 86
```
