Here's a simple React utility that removes widows from text by adjusting the line breaks. This utility uses the `react-syntax-highlighter` library for syntax highlighting.

```jsx
import React, { useState } from 'react';
import { SyntaxHighlighter } from 'react-syntax-highlighter';
import { atomOneDark } from 'react-syntax-highlighter/dist/cjs/styles/atomOneDark';

const RemoveWidows = ({ text }) => {
  const [widowedText, setWidowedText] = useState(text);

  const handleRemoveWidows = () => {
    const lines = widowedText.split('\n');
    const adjustedLines = lines.map((line) => {
      const words = line.split(' ');
      const lastWordIndex = words.length - 1;

      if (words[lastWordIndex].length > 0 && words[lastWordIndex - 1].length === 0) {
        words.pop();
      }

      return words.join(' ');
    });

    setWidowedText(adjustedLines.join('\n'));
  };

  return (
    <div>
      <SyntaxHighlighter language="javascript" style={atomOneDark}>
        {widowedText}
      </SyntaxHighlighter>
      <button onClick={handleRemoveWidows}>Remove Widows</button>
    </div>
  );
};

export default RemoveWidows;
```

To use this component, simply pass in the text you want to remove widows from:

```jsx
<RemoveWidows text="This is a sample text with some widows." />
```

This component will display the input text with syntax highlighting and a button to remove widows. When you click the button, the text will be adjusted to remove any widows.

